/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(tableStr(InventTransferLine))]
final class METInventTransferLineTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Reduce the Ship Remain qty to match what was pickied
    /// </summary>
    /// <param name = "_pickingRouteId">Picking route id</param>
    public static void METAdjustShipRemain(WMSPickingRouteID _pickingRouteId)
    {
        WMSOrderTrans               metWMSOrderTrans;
        InventTransferLine          metInventTransferLine;

        if(!METInventTransferTableExt::isAllowBackorderRouteId(_pickingRouteId))
        {
            while select forupdate metInventTransferLine
                join qty from metWMSOrderTrans
                where   metInventTransferLine.InventTransId == metWMSOrderTrans.inventTransId
                &&      metInventTransferLine.transferId    == metWMSOrderTrans.inventTransRefId
                &&      metWMSOrderTrans.routeId            == _pickingRouteId
                &&      metWMSOrderTrans.inventTransType    == InventTransType::TransferOrderShip
                //&&      metWMSOrderTrans.fullPallet         == NoYes::No - Obselete
            {
                metInventTransferLine.QtyRemainShip = metWMSOrderTrans.qty;

                if (metInventTransferLine.validateWrite())
                {
                    metInventTransferLine.updateDeliverRemainder(); //std code contains ttsbegin and ttscommit
                }
            }
        }
    }

    /// <summary>
    /// Update order extract status
    /// </summary>
    /// <param name = "_pickingRouteId">Picking route id</param>
    public static void metUpdateExtractionStatus(WMSPickingRouteID _pickingRouteId)
    {
        METWMSOrderTransTOView      metWMSOrderTransTOView;
        InventTransferLine          InventTransferLine;
        METInventTransferLine       metInventTransferLine;
        InventTransferTable         inventTransferTable;
        METInventTransferTableExt   inventTransferTableExt;

        update_recordset METInventTransferLine
            setting OrderExtractStatus = METOrderExtractStatus::Extracted
            join RecId from InventTransferLine
            where METInventTransferLine.inventTransferLine == InventTransferLine.RecId
            join RecId from inventTransferTable
            where   inventTransferTable.TransferId == inventTransferLine.TransferId
            join AllowBackorder from inventTransferTableExt
            where   inventTransferTableExt.InventTransferTable   == inventTransferTable.RecId
            join qty from metWMSOrderTransTOView
            where   InventTransferLine.InventTransId == metWMSOrderTransTOView.inventTransId
            &&      InventTransferLine.transferId    == metWMSOrderTransTOView.inventTransRefId
            &&      (!inventTransferTableExt.AllowBackorder || 
                    (inventTransferTableExt.AllowBackorder && metWMSOrderTransTOView.qty == InventTransferLine.QtyTransfer));

        update_recordset METInventTransferLine
            setting OrderExtractStatus = METOrderExtractStatus::Open
            join RecId from InventTransferLine
            where METInventTransferLine.inventTransferLine == InventTransferLine.RecId
            exists join inventTransferTable
            where   inventTransferTable.TransferId == inventTransferLine.TransferId
            exists join inventTransferTableExt
            where   inventTransferTableExt.InventTransferTable   == inventTransferTable.RecId
            && inventTransferTableExt.AllowBackorder == NoYes::Yes
            join qty from metWMSOrderTransTOView
            where   InventTransferLine.InventTransId == metWMSOrderTransTOView.inventTransId
            &&      InventTransferLine.transferId    == metWMSOrderTransTOView.inventTransRefId
            &&      inventTransferTableExt.AllowBackorder 
            &&      metWMSOrderTransTOView.qty != InventTransferLine.QtyTransfer;
    }

/// <summary>
/// Get the Invent Transfer Table Ext
/// </summary>
/// <returns>Invent Transfer Table Ext</returns>
public METInventTransferLine metInventTransferLine()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METInventTransferLine));
}

    /// <summary>
    /// pack the Invent Transfer Table Ext
    /// </summary>
    /// <param name = "_metInventTransferLine">METInventTransferLine to pack.</param>
    /// <param name = "_skipInit">
    /// CB395_CSDFulfilementInterBranchTransfer.
    /// Introduced this parameter to stop pack method from initializing values.
    /// Kept it as an optional argument to not break the existing processes.
    /// CB395_CSDFulfilementInterBranchTransfer.
    /// </param>
    public void metPackMETInventTransferLine(METInventTransferLine  _metInventTransferLine, boolean _skipInit = false)
    {
        _metInventTransferLine.InventTransferLine = this.RecId;

        if (!_skipInit)
        {
            _metInventTransferLine.initValue();
        }

        this.SysExtensionSerializerMap::packExtensionTable(_metInventTransferLine);
    }

    /// <summary>
    ///    Inserts a record into the database.
    /// </summary>
    /// <param name="_dropEstimated">
    ///    A <c>NoYes</c> enumeration; optional.
    /// </param>
    /// <remarks>
    ///    If yes is chosen for the optional <c>NoYes</c> enumeration parameter, the estimated transactions related to the line is not updated.
    /// </remarks>
    public void insert(NoYes _dropEstimated)
    {
        next insert(_dropEstimated);

        this.SysExtensionSerializerMap::postInsert();
    }

    /// <summary>
    /// Updates a record in the database.
    /// </summary>
    /// <param name="_parameters">
    /// Either a <c>InventTransferLineUpdateParameters</c> instance or (for backwards compatibility) a <c>NoYes</c> value to drop estimated data; optional.
    /// </param>
    /// <param name="_updateHeader">
    /// Indicates whether the header record must be updated; optional. This is only applicable when the first parameter is a <c>NoYes</c> value.
    /// </param>
    /// <remarks>
    /// If the <paramref name="_updateHeader" /> parameter is set to the <c>NoYes::Yes</c> enumeration
    /// value, the estimated transactions related to the line are not updated.
    /// </remarks>
    public void update(anytype _parameters, NoYes _updateHeader)
    {
        next update(_parameters, _updateHeader);

        this.SysExtensionSerializerMap::postUpdate();
    }
